// fullResponse + neverError : on juge sur le code HTTP, pas sur la forme du corps.
const res = $('Sweep Overdue Invoices').first().json || {};
const code = res.statusCode || 0;
const body = res.body || {};

if (code !== 200) {
  // 401 = CONTRAVO_CRON_SECRET absent ou desynchronise de CRON_SECRET cote app.
  throw new Error(`Invoice reminder sweep failed: HTTP ${code} ${JSON.stringify(body).slice(0, 300)}`);
}

// Un echec par facture n'arrete pas la passe : on le remonte quand meme, sinon
// une relance jamais envoyee resterait invisible.
if ((body.failures ?? 0) > 0) {
  const failed = (body.details || []).filter((d) => d.outcome === 'failed');
  throw new Error(`${body.failures} relance(s) en echec : ${JSON.stringify(failed).slice(0, 400)}`);
}

return [{ json: { ok: true, remindersSent: body.remindersSent ?? 0, markedOverdue: body.markedOverdue ?? 0, alreadySent: body.alreadySent ?? 0 } }];
